import { DomainError } from "./product";

export const orderStates = ["placed", "paid", "packed", "shipped", "delivered"] as const;
export type OrderState = (typeof orderStates)[number];

export interface OrderItem {
  productId: string;
  quantity: number;
}

export interface Order {
  id: string;
  items: OrderItem[];
  state: OrderState;
  cancelled: boolean;
}

export function createOrder(id: string, items: OrderItem[]): Order {
  if (!id) throw new DomainError("Order id is required");
  if (items.length === 0) throw new DomainError("An order must contain at least one item");
  const quantities = new Map<string, number>();
  for (const item of items) {
    if (!item.productId.trim()) throw new DomainError("Product id is required");
    if (!Number.isSafeInteger(item.quantity) || item.quantity <= 0) {
      throw new DomainError("Item quantity must be a positive integer");
    }
    quantities.set(item.productId, (quantities.get(item.productId) ?? 0) + item.quantity);
  }
  return {
    id,
    items: [...quantities].map(([productId, quantity]) => ({ productId, quantity })),
    state: "placed",
    cancelled: false,
  };
}

export function transitionOrder(order: Order, state: OrderState): void {
  if (order.cancelled) throw new DomainError("A cancelled order cannot be changed");
  const currentIndex = orderStates.indexOf(order.state);
  if (orderStates[currentIndex + 1] !== state) {
    throw new DomainError(`Order can only move from ${order.state} to ${orderStates[currentIndex + 1] ?? "no further state"}`);
  }
  order.state = state;
}

export function cancelOrder(order: Order): void {
  if (order.cancelled) throw new DomainError("Order is already cancelled");
  if (order.state === "shipped" || order.state === "delivered") {
    throw new DomainError("A shipped order cannot be cancelled");
  }
  order.cancelled = true;
}

